536→// fetchTrailsBranch fetches the remote trails branch so we see trails from collaborators.
537→// Best-effort: silently ignores errors (e.g., no remote, no network).
538→func fetchTrailsBranch() {
539→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
540→	defer cancel()
541→	branchName := paths.TrailsBranchName
542→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
543→
544→	cmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
545→	// Ensure non-interactive fetch in hook/agent contexts
546→	cmd.Stdin = nil
547→	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
548→	_ = cmd.Run() //nolint:errcheck // best-effort fetch
549→}
