551→// getTrailAuthor returns the GitHub username for the trail author.
552→// Falls back to git user.name if gh CLI is unavailable or not authenticated.
553→func getTrailAuthor(repo *git.Repository) string {
554→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
555→	defer cancel()
556→	cmd := exec.CommandContext(ctx, "gh", "api", "user", "-q", ".login")
557→	if output, err := cmd.Output(); err == nil {
558→		if login := strings.TrimSpace(string(output)); login != "" {
559→			return login
560→		}
561→	}
562→	name, _ := strategy.GetGitAuthorFromRepo(repo)
563→	return name
564→}
