14→// Windows has no concept of parent/child processes or signals. The best we can do
15→// is create processes inside a "console group" and then send break / ctrl-c events
16→// to that group. This is superior to walking a process tree to kill each process
17→// because that relies on each process in that chain still being active.
18→
19→// See https://docs.microsoft.com/en-us/windows/console/generateconsolectrlevent
20→
21→func (p *Process) setupProcessGroup() {
22→	if p.conf.PTY {
23→		return
24→	}
25→	p.command.SysProcAttr = &windows.SysProcAttr{
26→		CreationFlags: windows.CREATE_UNICODE_ENVIRONMENT | windows.CREATE_NEW_PROCESS_GROUP,
27→	}
28→	jobHandle, err := newJobObject()
29→	if err != nil {
30→		p.logger.Error("Creating Job Object failed: %v", err)
31→	}
32→	p.winJobHandle = jobHandle
33→}
34→
35→func newJobObject() (uintptr, error) {
36→	handle, err := windows.CreateJobObject(nil, nil)
37→	if err != nil {
38→		return 0, err
39→	}
40→
41→	info := windows.JOBOBJECT_EXTENDED_LIMIT_INFORMATION{
42→		BasicLimitInformation: windows.JOBOBJECT_BASIC_LIMIT_INFORMATION{
43→			LimitFlags: windows.JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE,
44→		},
45→	}
46→	if _, err := windows.SetInformationJobObject(
47→		handle,
48→		windows.JobObjectExtendedLimitInformation,
49→		uintptr(unsafe.Pointer(&info)),
50→		uint32(unsafe.Sizeof(info))); err != nil {
51→		return 0, err
52→	}
53→
54→	return uintptr(handle), nil
55→}
56→
57→func (p *Process) postStart() error {
58→	// convert the pid into a windows process handle. We need particular permissions on the handle
59→	// for AssignProcessToJobObject to accept it
60→	pid := uint32(p.command.Process.Pid)
61→	processPerms := uint32(windows.PROCESS_QUERY_LIMITED_INFORMATION | windows.PROCESS_SET_QUOTA | windows.PROCESS_TERMINATE)
62→	processHandle, err := windows.OpenProcess(processPerms, false, pid)
63→	if err != nil {
64→		return err
65→	}
66→	defer windows.CloseHandle(processHandle)
67→
68→	err = windows.AssignProcessToJobObject(windows.Handle(p.winJobHandle), processHandle)
69→	if err != nil {
70→		return err
71→	}
72→	return nil
73→}
74→
75→func (p *Process) terminateProcessGroup() error {
76→	p.logger.Debug("[Process] Terminating process tree by destroying job")
77→	return windows.CloseHandle(windows.Handle(p.winJobHandle))
78→}
79→
80→func (p *Process) interruptProcessGroup() error {
81→	// Sends a CTRL-BREAK signal to the process group id, which is the same as the process PID
82→	// For some reason I cannot fathom, this returns "Incorrect function" in docker for windows
83→	err := windows.GenerateConsoleCtrlEvent(windows.CTRL_BREAK_EVENT, uint32(p.pid))
84→	if err != nil {
85→		return err
86→	}
87→	return nil
88→}
