18→func chkStat(file string) error {
19→	d, err := os.Stat(file)
20→	if err != nil {
21→		return err
22→	}
23→	if d.IsDir() {
24→		return os.ErrPermission
25→	}
26→	return nil
27→}
28→
29→func hasExt(file string) bool {
30→	i := strings.LastIndex(file, ".")
31→	if i < 0 {
32→		return false
33→	}
34→	return strings.LastIndexAny(file, `:\/`) < i
35→}
36→
37→func findExecutable(file string, exts []string) (string, error) {
38→	if len(exts) == 0 {
39→		return file, chkStat(file)
40→	}
41→	if hasExt(file) {
42→		if chkStat(file) == nil {
43→			return file, nil
44→		}
45→	}
46→	for _, e := range exts {
47→		if f := file + e; chkStat(f) == nil {
48→			return f, nil
49→		}
50→	}
51→	return "", os.ErrNotExist
52→}
