54→// LookPath searches for an executable binary named file in the directories within the path variable,
55→// which is a semi-colon delimited path.
56→// If file contains a slash, it is tried directly
57→// LookPath also uses PATHEXT environment variable to match a suitable candidate.
58→// The result may be an absolute path or a path relative to the current directory.
59→func LookPath(file, path, fileExtensions string) (string, error) {
60→	var exts []string
61→	if fileExtensions != "" {
62→		for _, e := range strings.Split(strings.ToLower(fileExtensions), ";") {
63→			if e == "" {
64→				continue
65→			}
66→			if e[0] != '.' {
67→				e = "." + e
68→			}
69→			exts = append(exts, e)
70→		}
71→	} else {
72→		exts = []string{".com", ".exe", ".bat", ".cmd"}
73→	}
74→
75→	if strings.ContainsAny(file, `:\/`) {
76→		if f, err := findExecutable(file, exts); err == nil {
77→			return f, nil
78→		} else {
79→			return "", &exec.Error{file, err}
80→		}
81→	}
82→	if f, err := findExecutable(filepath.Join(".", file), exts); err == nil {
83→		return f, nil
84→	}
85→	for _, dir := range filepath.SplitList(path) {
86→		if f, err := findExecutable(filepath.Join(dir, file), exts); err == nil {
87→			return f, nil
88→		}
89→	}
90→	return "", &exec.Error{file, exec.ErrNotFound}
91→}
