359→// readCheckpointMetadata reads metadata.json from a checkpoint path on entire/checkpoints/v1.
360→// With the new format, root metadata.json is a CheckpointSummary with Agents array.
361→// This function reads the summary and extracts relevant fields into CheckpointInfo,
362→// also reading session-level metadata for IsTask/ToolUseID fields.
363→func ReadCheckpointMetadata(tree *object.Tree, checkpointPath string) (*CheckpointInfo, error) {
364→	metadataPath := checkpointPath + "/metadata.json"
365→	file, err := tree.File(metadataPath)
366→	if err != nil {
367→		return nil, fmt.Errorf("failed to find metadata at %s: %w", metadataPath, err)
368→	}
369→
370→	content, err := file.Contents()
371→	if err != nil {
372→		return nil, fmt.Errorf("failed to read metadata: %w", err)
373→	}
374→
375→	// Try to parse as CheckpointSummary first (new format)
376→	var summary checkpoint.CheckpointSummary
377→	if err := json.Unmarshal([]byte(content), &summary); err == nil {
378→		// If we have sessions array, this is the new format
379→		if len(summary.Sessions) > 0 {
380→			info := &CheckpointInfo{
381→				CheckpointID:     summary.CheckpointID,
382→				CheckpointsCount: summary.CheckpointsCount,
383→				FilesTouched:     summary.FilesTouched,
384→				SessionCount:     len(summary.Sessions),
385→			}
386→
387→			// Read all sessions' metadata to populate SessionIDs and get other fields from first session
388→			var sessionIDs []string
389→			for i, sessionPaths := range summary.Sessions {
390→				if sessionPaths.Metadata != "" {
391→					// SessionFilePaths now contains absolute paths with leading "/"
392→					// Strip the leading "/" for tree.File() which expects paths without leading slash
393→					sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
394→					if sessionFile, err := tree.File(sessionMetadataPath); err == nil {
395→						if sessionContent, err := sessionFile.Contents(); err == nil {
396→							var sessionMetadata checkpoint.CommittedMetadata
397→							if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
398→								sessionIDs = append(sessionIDs, sessionMetadata.SessionID)
399→								// Use first session for Agent, SessionID, CreatedAt, IsTask, ToolUseID
400→								if i == 0 {
401→									info.Agent = sessionMetadata.Agent
402→									info.SessionID = sessionMetadata.SessionID
403→									info.CreatedAt = sessionMetadata.CreatedAt
404→									info.IsTask = sessionMetadata.IsTask
405→									info.ToolUseID = sessionMetadata.ToolUseID
406→								}
407→							}
408→						}
409→					}
410→				}
411→			}
412→			info.SessionIDs = sessionIDs
413→
414→			return info, nil
415→		}
416→	}
417→
418→	// Fall back to parsing as CheckpointInfo (old format or direct info)
419→	var metadata CheckpointInfo
420→	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
421→		return nil, fmt.Errorf("failed to parse metadata: %w", err)
422→	}
423→
424→	return &metadata, nil
