 40→// Split splits an environment variable (in the form "name=value") into the name
 41→// and value substrings. If there is no '=', or the first '=' is at the start,
 42→// it returns `"", "", false`.
 43→func Split(l string) (name, value string, ok bool) {
 44→	// Variable names should not contain '=' on any platform...and yet Windows
 45→	// creates environment variables beginning with '=' in some circumstances.
 46→	// See https://github.com/golang/go/issues/49886.
 47→	// Dropping them matches the previous behaviour on Windows, which used SET
 48→	// to obtain the state of environment variables.
 49→	i := strings.IndexRune(l, '=')
 50→	// Either there is no '=', or it is at the start of the string.
 51→	// Both are disallowed.
 52→	if i <= 0 {
 53→		return "", "", false
 54→	}
 55→	return l[:i], l[i+1:], true
 56→}
