 58→// FromSlice creates a new environment from a string slice of KEY=VALUE
 59→func FromSlice(s []string) *Environment {
 60→	env := NewWithLength(len(s))
 61→
 62→	for _, l := range s {
 63→		if k, v, ok := Split(l); ok {
 64→			env.Set(k, v)
 65→		}
 66→	}
 67→
 68→	return env
 69→}
