132→// GetString gets a string value from environment, with a default for unset or
133→// empty values.
134→func (e *Environment) GetString(key, defaultValue string) string {
135→	v, has := e.Get(key)
136→	if !has || v == "" {
137→		return defaultValue
138→	}
139→	return v
140→}
141→
142→// Exists returns true/false depending on whether or not the key exists in the env
143→func (e *Environment) Exists(key string) bool {
144→	_, ok := e.underlying.Load(normalizeKeyName(key))
145→	return ok
146→}
147→
148→// Set sets a key in the environment
149→func (e *Environment) Set(key, value string) {
150→	e.underlying.Store(normalizeKeyName(key), value)
151→}
152→
153→// Remove a key from the Environment and return its value
154→func (e *Environment) Remove(key string) string {
155→	value, ok := e.Get(key)
156→	if ok {
157→		e.underlying.Delete(normalizeKeyName(key))
158→	}
159→	return value
160→}
161→
162→// Length returns the length of the environment
163→func (e *Environment) Length() int {
164→	return e.underlying.Size()
165→}
166→
167→// Diff returns a new environment with the keys and values from this
168→// environment which are different in the other one.
169→func (e *Environment) Diff(other *Environment) Diff {
170→	diff := Diff{
171→		Added:   make(map[string]string),
172→		Changed: make(map[string]DiffPair),
173→		Removed: make(map[string]struct{}, 0),
174→	}
175→
176→	if other == nil {
177→		e.underlying.Range(func(k, _ string) bool {
178→			diff.Removed[k] = struct{}{}
179→			return true
180→		})
181→
182→		return diff
183→	}
184→
185→	e.underlying.Range(func(k, v string) bool {
186→		other, ok := other.Get(k)
187→		if !ok {
188→			// This environment has added this key to other
189→			diff.Added[k] = v
190→			return true
191→		}
192→
193→		if other != v {
194→			diff.Changed[k] = DiffPair{
195→				Old: other,
196→				New: v,
197→			}
198→		}
199→
200→		return true
201→	})
202→
203→	other.underlying.Range(func(k, _ string) bool {
204→		if _, ok := e.Get(k); !ok {
205→			diff.Removed[k] = struct{}{}
206→		}
207→
208→		return true
209→	})
210→
211→	return diff
212→}
213→
214→// Merge merges another env into this one and returns the result
215→func (e *Environment) Merge(other *Environment) {
216→	if other == nil {
217→		return
218→	}
219→
220→	other.underlying.Range(func(k, v string) bool {
221→		e.Set(k, v)
222→		return true
223→	})
224→}
225→
226→func (e *Environment) Apply(diff Diff) {
227→	for k, v := range diff.Added {
228→		e.Set(k, v)
229→	}
230→	for k, v := range diff.Changed {
231→		e.Set(k, v.New)
232→	}
233→	for k := range diff.Removed {
234→		e.Remove(k)
235→	}
236→}
237→
238→// Copy returns a copy of the env
239→func (e *Environment) Copy() *Environment {
240→	if e == nil {
241→		return New()
242→	}
243→
244→	c := New()
245→
246→	e.underlying.Range(func(k, v string) bool {
247→		c.Set(k, v)
248→		return true
249→	})

