1090→// - Deleted files (to exclude from checkpoint tree)
1091→//
1092→// The base tree from HEAD already contains all unchanged tracked files.
1093→//
1094→// Uses `git status --porcelain -z` for reliable parsing of filenames with special characters.
1095→func collectChangedFiles(ctx context.Context, repo *git.Repository) (changedFilesResult, error) {
1096→	// Get worktree root directory for running git command
1097→	wt, err := repo.Worktree()
1098→	if err != nil {
1099→		return changedFilesResult{}, fmt.Errorf("failed to get worktree: %w", err)
1100→	}
1101→	repoRoot := wt.Filesystem.Root()
1102→
1103→	// Use -z for NUL-separated output (handles quoted filenames with spaces/special chars)
1104→	// Use -uall to list individual untracked files instead of collapsed directories.
1105→	// Note: CLAUDE.md warns against -uall for user-facing display, but we need the full list
1106→	// for checkpointing.
1107→	cmd := exec.CommandContext(ctx, "git", "status", "--porcelain", "-z", "-uall")
1108→	cmd.Dir = repoRoot
1109→	output, err := cmd.Output()
1110→	if err != nil {
1111→		return changedFilesResult{}, fmt.Errorf("failed to get git status in %s: %w", repoRoot, err)
1112→	}
1113→
1114→	changedSeen := make(map[string]struct{})
1115→	deletedSeen := make(map[string]struct{})
1116→
1117→	// Parse NUL-separated output
1118→	// Format: XY filename\0 (for most entries)
1119→	// For renames/copies: XY newname\0oldname\0
1120→	entries := strings.Split(string(output), "\x00")
1121→
1122→	for i := 0; i < len(entries); i++ {
1123→		entry := entries[i]
1124→		if len(entry) < 3 {
1125→			continue
1126→		}
1127→
1128→		// git status --porcelain format: XY filename
1129→		// X = staging status, Y = worktree status
1130→		staging := entry[0]
1131→		wtStatus := entry[1]
1132→		filename := entry[3:] // No TrimSpace needed with -z format
1133→
1134→		// Handle R/C (rename/copy) first - they have a second entry we must skip
1135→		// even if the new filename is an infrastructure path
1136→		if staging == 'R' || staging == 'C' {
1137→			// Renamed or copied: current entry is new name, next entry is old name
1138→			if !paths.IsInfrastructurePath(filename) {
1139→				changedSeen[filename] = struct{}{}
1140→			}
1141→			// The old name follows as the next NUL-separated entry - must always skip it
1142→			if i+1 < len(entries) && entries[i+1] != "" {
1143→				oldName := entries[i+1]
1144→				if staging == 'R' && !paths.IsInfrastructurePath(oldName) {
1145→					// For renames, old file is effectively deleted
1146→					deletedSeen[oldName] = struct{}{}
1147→				}
1148→				i++ // Skip the old name entry
1149→			}
1150→			continue
1151→		}
1152→
1153→		// Skip .entire directory for non-R/C entries
1154→		if paths.IsInfrastructurePath(filename) {
1155→			continue
1156→		}
1157→
1158→		// Handle different status codes
1159→		switch {
1160→		case staging == 'D' || wtStatus == 'D':
1161→			// Deleted file - track separately
1162→			deletedSeen[filename] = struct{}{}
1163→
1164→		case wtStatus == 'M' || wtStatus == 'A':
1165→			// Modified or added in worktree
1166→			changedSeen[filename] = struct{}{}
1167→
1168→		case staging == '?' && wtStatus == '?':
1169→			// Untracked file
1170→			changedSeen[filename] = struct{}{}
1171→
1172→		case staging == 'A' || staging == 'M':
1173→			// Staged add or modify
1174→			changedSeen[filename] = struct{}{}
1175→
1176→		case staging == 'T' || wtStatus == 'T':
1177→			// Type change (e.g., file to symlink)
1178→			changedSeen[filename] = struct{}{}
1179→
1180→		case staging == 'U' || wtStatus == 'U':
1181→			// Unmerged (conflict) - include current file state
1182→			changedSeen[filename] = struct{}{}
1183→		}
1184→	}
1185→
1186→	changed := make([]string, 0, len(changedSeen))
1187→	for file := range changedSeen {
1188→		changed = append(changed, file)
1189→	}

