20→func findExecutable(file string) error {
21→	d, err := os.Stat(file)
22→	if err != nil {
23→		return err
24→	}
25→	if m := d.Mode(); !m.IsDir() && m&0o111 != 0 {
26→		return nil
27→	}
28→	return os.ErrPermission
29→}
