31→// LookPath searches for an executable binary named file in the directories within the path variable,
32→// which is a colon delimited path.
33→// If file contains a slash, it is tried directly
34→func LookPath(file, path, fileExtensions string) (string, error) {
35→	if strings.Contains(file, "/") {
36→		err := findExecutable(file)
37→		if err == nil {
38→			return file, nil
39→		}
40→		return "", &exec.Error{Name: file, Err: err}
41→	}
42→	for _, dir := range filepath.SplitList(path) {
43→		if dir == "" {
44→			// Unix shell semantics: path element "" means "."
45→			dir = "."
46→		}
47→		path := filepath.Join(dir, file)
48→		if err := findExecutable(path); err == nil {
49→			return path, nil
50→		}
51→	}
52→	return "", &exec.Error{Name: file, Err: exec.ErrNotFound}
53→}
