 69→// ChunkTranscript splits an OpenCode export JSON transcript by distributing messages across chunks.
 70→// OpenCode uses JSON format with {"info": {...}, "messages": [...]} structure.
 71→func (a *OpenCodeAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
 72→	var session ExportSession
 73→	if err := json.Unmarshal(content, &session); err != nil {
 74→		return nil, fmt.Errorf("failed to parse export session for chunking: %w", err)
 75→	}
 76→
 77→	if len(session.Messages) == 0 {
 78→		return [][]byte{content}, nil
 79→	}
 80→
 81→	// Marshal info to calculate accurate base size
 82→	infoBytes, err := json.Marshal(session.Info)
 83→	if err != nil {
 84→		return nil, fmt.Errorf("failed to marshal session info for chunking: %w", err)
 85→	}
 86→	// Base JSON structure size: {"info":<info>,"messages":[ ... ]}
 87→	baseSize := len(`{"info":`) + len(infoBytes) + len(`,"messages":[]}`)
 88→
 89→	var chunks [][]byte
 90→	var currentMessages []ExportMessage
 91→	currentSize := baseSize
 92→
 93→	for _, msg := range session.Messages {
 94→		// Marshal message to get its size
 95→		msgBytes, err := json.Marshal(msg)
 96→		if err != nil {
 97→			return nil, fmt.Errorf("failed to marshal message for chunking: %w", err)
 98→		}
 99→		msgSize := len(msgBytes) + 1 // +1 for comma separator
100→
101→		if currentSize+msgSize > maxSize && len(currentMessages) > 0 {
102→			// Save current chunk
103→			chunkData, err := json.Marshal(ExportSession{Info: session.Info, Messages: currentMessages})
104→			if err != nil {
105→				return nil, fmt.Errorf("failed to marshal chunk: %w", err)
106→			}
107→			chunks = append(chunks, chunkData)
108→
109→			// Start new chunk
110→			currentMessages = nil
111→			currentSize = baseSize
112→		}
113→
114→		currentMessages = append(currentMessages, msg)
115→		currentSize += msgSize
116→	}
117→
118→	// Add the last chunk
119→	if len(currentMessages) > 0 {
120→		chunkData, err := json.Marshal(ExportSession{Info: session.Info, Messages: currentMessages})
121→		if err != nil {
122→			return nil, fmt.Errorf("failed to marshal final chunk: %w", err)
123→		}
124→		chunks = append(chunks, chunkData)
125→	}
126→
127→	if len(chunks) == 0 {
128→		return nil, errors.New("failed to create any chunks")
129→	}
130→
131→	return chunks, nil
132→}
133→
134→// ReassembleTranscript merges OpenCode export JSON chunks by combining their message arrays.
135→func (a *OpenCodeAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
136→	if len(chunks) == 0 {
137→		return nil, errors.New("no chunks to reassemble")
138→	}
139→
140→	var allMessages []ExportMessage
141→	var sessionInfo SessionInfo
142→
143→	for i, chunk := range chunks {
144→		var session ExportSession
145→		if err := json.Unmarshal(chunk, &session); err != nil {
146→			return nil, fmt.Errorf("failed to unmarshal chunk %d: %w", i, err)
147→		}
148→		if i == 0 {
149→			sessionInfo = session.Info // Preserve session info from first chunk
150→		}

  1→package strategy
  2→
  3→import (
  4→	"context"
  5→	"fmt"
  6→	"io"
  7→	"os"
  8→	"path/filepath"
  9→	"strings"
 10→
 11→	"github.com/entireio/cli/cmd/entire/cli/paths"
 12→)
 13→
 14→// hookManager describes an external hook manager detected in a repository.
 15→type hookManager struct {
 16→	Name            string // "Husky", "Lefthook", "pre-commit", "Overcommit"
 17→	ConfigPath      string // relative path that triggered detection (e.g., ".husky/")
 18→	OverwritesHooks bool   // true if the tool will overwrite Entire's hooks on reinstall
 19→}
 20→
 21→// detectHookManagers checks the repository root for known hook manager config
 22→// files/directories. Detection is filesystem-only (os.Stat, no file reads).
 23→func detectHookManagers(repoRoot string) []hookManager {
 24→	var managers []hookManager
 25→
 26→	checks := []hookManager{
 27→		{"Husky", ".husky/", true},
 28→		{"pre-commit", ".pre-commit-config.yaml", false},
 29→		{"Overcommit", ".overcommit.yml", false},
 30→	}
 31→
 32→	// Lefthook supports {.,}lefthook{,-local}.{yml,yaml,json,toml}
 33→	for _, prefix := range []string{"", "."} {
 34→		for _, variant := range []string{"", "-local"} {
 35→			for _, ext := range []string{"yml", "yaml", "json", "toml"} {
 36→				name := prefix + "lefthook" + variant + "." + ext
 37→				checks = append(checks, hookManager{"Lefthook", name, false})
 38→			}
 39→		}
 40→	}
 41→
 42→	seen := make(map[string]bool)
 43→	for _, c := range checks {
 44→		path := filepath.Join(repoRoot, c.ConfigPath)
 45→		if _, err := os.Stat(path); err == nil {
 46→			if seen[c.Name] {
 47→				continue // e.g., lefthook.yml and .lefthook.yml both present
 48→			}
 49→			seen[c.Name] = true
 50→			managers = append(managers, c)
 51→		}
 52→	}
 53→
 54→	return managers
 55→}
 56→
 57→// hookManagerWarning builds a warning string for detected hook managers.
 58→// cmdPrefix is the CLI command prefix (e.g., "entire" or "go run ./cmd/entire/main.go").
 59→func hookManagerWarning(managers []hookManager, cmdPrefix string) string {
 60→	if len(managers) == 0 {
 61→		return ""
 62→	}
 63→
 64→	var b strings.Builder
 65→
 66→	specs := buildHookSpecs(cmdPrefix)
 67→
 68→	for _, m := range managers {
 69→		if m.OverwritesHooks {
 70→			fmt.Fprintf(&b, "Warning: %s detected (%s)\n", m.Name, m.ConfigPath)
 71→			fmt.Fprintf(&b, "\n")
 72→			fmt.Fprintf(&b, "  %s may overwrite hooks installed by Entire on npm install.\n", m.Name)
 73→			fmt.Fprintf(&b, "  To make Entire hooks permanent, add these lines to your %s hook files:\n", m.Name)
 74→			fmt.Fprintf(&b, "\n")
 75→
 76→			// Use the config path as the hook directory prefix for hook files.
 77→			// For Husky, this is typically ".husky/" where hook scripts are stored.
 78→			hookDir := m.ConfigPath
 79→
 80→			for _, spec := range specs {
 81→				cmdLine := extractCommandLine(spec.content)
 82→				if cmdLine == "" {
 83→					continue
 84→				}
 85→				fmt.Fprintf(&b, "    %s%s:\n", hookDir, spec.name)
 86→				fmt.Fprintf(&b, "      %s\n", cmdLine)
 87→				fmt.Fprintf(&b, "\n")
 88→			}
 89→		} else {
 90→			fmt.Fprintf(&b, "Note: %s detected (%s)\n", m.Name, m.ConfigPath)
 91→			fmt.Fprintf(&b, "\n")
 92→			fmt.Fprintf(&b, "  If %s reinstalls hooks, run 'entire enable' to restore Entire's hooks.\n", m.Name)
 93→			fmt.Fprintf(&b, "\n")
 94→		}
 95→	}
 96→
 97→	return b.String()
 98→}
 99→
100→// extractCommandLine returns the first non-shebang, non-comment, non-empty line
101→// from a hook script. This is the actual command invocation line.
102→func extractCommandLine(hookContent string) string {
103→	for _, line := range strings.Split(hookContent, "\n") {
104→		trimmed := strings.TrimSpace(line)
105→		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
106→			continue
107→		}
108→		return trimmed
109→	}
110→	return ""
111→}
112→
113→// CheckAndWarnHookManagers detects external hook managers and writes a warning
114→// to w if any are found.
115→// localDev controls whether the warning references "go run" or the "entire" binary.
116→// absolutePath embeds the full binary path for GUI git clients.
117→func CheckAndWarnHookManagers(ctx context.Context, w io.Writer, localDev, absolutePath bool) {
118→	repoRoot, err := paths.WorktreeRoot(ctx)
119→	if err != nil {
120→		return
121→	}
122→
123→	managers := detectHookManagers(repoRoot)
124→	if len(managers) == 0 {
125→		return
126→	}
127→
128→	cmdPrefix, err := hookCmdPrefix(localDev, absolutePath)
129→	if err != nil {
130→		// Best-effort: hook manager warnings are advisory, skip on resolution failure
131→		return
132→	}
133→	warning := hookManagerWarning(managers, cmdPrefix)
134→	if warning != "" {
135→		fmt.Fprintln(w)
136→		fmt.Fprint(w, warning)
137→	}
138→}
