 14→// cleanConfigDir creates an isolated temp directory for CLAUDE_CONFIG_DIR so
 15→// that E2E test runs don't inherit any user settings (CLAUDE.md, skills,
 16→// projects, plugins, etc.).
 17→//
 18→// On CI, it symlinks .claude.json (which Bootstrap() wrote with the API key
 19→// and hasCompletedOnboarding). Locally, it writes a minimal .claude.json to
 20→// skip the onboarding flow — Keychain-based auth works without any other files.
 21→func cleanConfigDir() (string, error) {
 22→	dst, err := os.MkdirTemp("", "claude-config-*")
 23→	if err != nil {
 24→		return "", err
 25→	}
 26→
 27→	if os.Getenv("CI") != "" {
 28→		if home, err := os.UserHomeDir(); err == nil {
 29→			src := filepath.Join(home, ".claude", ".claude.json")
 30→			if _, err := os.Stat(src); err == nil {
 31→				_ = os.Symlink(src, filepath.Join(dst, ".claude.json"))
 32→			}
 33→		}
 34→	} else {
 35→		_ = os.WriteFile(filepath.Join(dst, ".claude.json"),
 36→			[]byte(`{"hasCompletedOnboarding":true}`), 0o644)
 37→	}
 38→
 39→	return dst, nil
 40→}
