 42→// cleanEnv returns os.Environ() with agent-incompatible variables removed.
 43→// It strips CLAUDECODE (so Claude Code doesn't refuse to start inside this
 44→// test runner) and ENTIRE_TEST_TTY (so agents exercise the real TTY detection
 45→// paths instead of the test override).
 46→func cleanEnv() []string {
 47→	var env []string
 48→	for _, e := range os.Environ() {
 49→		if strings.HasPrefix(e, "CLAUDECODE=") || strings.HasPrefix(e, "ENTIRE_TEST_TTY=") {
 50→			continue
 51→		}
 52→		env = append(env, e)
 53→	}
 54→	return env
 55→}
