 64→type Claude struct{}
 65→
 66→func (c *Claude) Name() string               { return "claude-code" }
 67→func (c *Claude) Binary() string             { return "claude" }
 68→func (c *Claude) EntireAgent() string        { return "claude-code" }
 69→func (c *Claude) PromptPattern() string      { return `❯` }
 70→func (c *Claude) TimeoutMultiplier() float64 { return 1.0 }
 71→
 72→func (c *Claude) IsTransientError(out Output, _ error) bool {
 73→	transientPatterns := []string{
 74→		"overloaded",
 75→		"rate limit",
 76→		"529",
 77→		"503",
 78→		"ECONNRESET",
 79→		"ETIMEDOUT",
 80→	}
 81→	for _, p := range transientPatterns {
 82→		if strings.Contains(out.Stderr, p) {
 83→			return true
 84→		}
 85→	}
 86→	return false
 87→}
