 89→func (c *Claude) Bootstrap() error {
 90→	// On CI, write a config file so Claude Code uses the API key from the
 91→	// environment instead of trying OAuth/Keychain.
 92→	if os.Getenv("CI") == "" {
 93→		return nil
 94→	}
 95→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
 96→	if apiKey == "" {
 97→		return nil
 98→	}
 99→	home, err := os.UserHomeDir()
100→	if err != nil {
101→		return fmt.Errorf("get home dir: %w", err)
102→	}
103→	dir := filepath.Join(home, ".claude")
104→	if err := os.MkdirAll(dir, 0o755); err != nil {
105→		return fmt.Errorf("mkdir %s: %w", dir, err)
106→	}
107→	config := fmt.Sprintf(`{"primaryApiKey":%q,"hasCompletedOnboarding":true}`, apiKey)
108→	path := filepath.Join(dir, ".claude.json")
109→	return os.WriteFile(path, []byte(config), 0o644)
110→}
