112→func (c *Claude) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
113→	cfg := &runConfig{Model: "haiku"}
114→	for _, o := range opts {
115→		o(cfg)
116→	}
117→
118→	configDir, err := cleanConfigDir()
119→	if err != nil {
120→		return Output{}, fmt.Errorf("create clean config dir: %w", err)
121→	}
122→	defer func() { _ = os.RemoveAll(configDir) }()
123→
124→	env := append(cleanEnv(),
125→		"ACCESSIBLE=1",
126→
127→		// See https://code.claude.com/docs/en/settings - without this setting Claude was going off and
128→		// trying to Git-clone its plugin marketplace, which meant calling git commands that could fail
129→		// due to a user's exotic config (e.g. in paul's case, needing SSH-keychain access granted every
130→		// time).  That's no good, so for the E2E tests, we tell Claude not to make calls to auto-update
131→		// itself, clone its plugins, etc.
132→		"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1",
133→		"CLAUDE_CONFIG_DIR="+configDir,
134→	)
135→
136→	args := []string{"-p", prompt, "--model", cfg.Model, "--dangerously-skip-permissions"}
137→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--dangerously-skip-permissions"}
138→	cmd := exec.CommandContext(ctx, c.Binary(), args...)
139→	cmd.Dir = dir
140→	cmd.Stdin = nil
141→	cmd.Env = env
142→	setupProcessGroup(cmd)
143→	cmd.WaitDelay = 5 * time.Second
144→
145→	var stdout, stderr strings.Builder
146→	cmd.Stdout = &stdout
147→	cmd.Stderr = &stderr
148→
149→	err = cmd.Run()
150→	exitCode := 0
151→	if err != nil {
152→		exitErr := &exec.ExitError{}
153→		if errors.As(err, &exitErr) {
154→			exitCode = exitErr.ExitCode()
155→		} else {
156→			exitCode = -1
157→		}
158→	}
159→
160→	return Output{
161→		Command:  c.Binary() + " " + strings.Join(displayArgs, " "),
162→		Stdout:   stdout.String(),
163→		Stderr:   stderr.String(),
164→		ExitCode: exitCode,
165→	}, err
166→}
