168→func (c *Claude) StartSession(ctx context.Context, dir string) (Session, error) {
169→	name := fmt.Sprintf("claude-test-%d", time.Now().UnixNano())
170→
171→	configDir, err := cleanConfigDir()
172→	if err != nil {
173→		return nil, fmt.Errorf("create clean config dir: %w", err)
174→	}
175→
176→	envArgs := []string{
177→		"ACCESSIBLE=1",
178→
179→		// See https://code.claude.com/docs/en/settings - without this setting Claude was going off and
180→		// trying to Git-clone its plugin marketplace, which meant calling git commands that could fail
181→		// due to a user's exotic config (e.g. in paul's case, needing SSH-keychain access granted every
182→		// time).  That's no good, so for the E2E tests, we tell Claude not to make calls to auto-update
183→		// itself, clone its plugins, etc.
184→		"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1",
185→		"CLAUDE_CONFIG_DIR=" + configDir,
186→	}
187→
188→	args := append([]string{"env"}, envArgs...)
189→	args = append(args, c.Binary(), "--dangerously-skip-permissions")
190→	s, err := NewTmuxSession(name, dir, []string{"CLAUDECODE", "ENTIRE_TEST_TTY"}, args[0], args[1:]...)
191→	if err != nil {
192→		_ = os.RemoveAll(configDir)
193→		return nil, err
194→	}
195→	s.OnClose(func() { _ = os.RemoveAll(configDir) })
196→
197→	// Dismiss startup dialogs until we reach the input prompt.
198→	for range 5 {
199→		content, err := s.WaitFor(`❯`, 15*time.Second)
200→		if err != nil {
201→			_ = s.Close()
202→			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
203→		}
204→		if !strings.Contains(content, "Enter to confirm") {
205→			break
206→		}
207→		// The bypass permissions dialog defaults to "No, exit" —
208→		// arrow down to "Yes, I accept" before confirming.
209→		if strings.Contains(content, "Yes, I accept") {
210→			_ = s.SendKeys("Down")
211→			time.Sleep(200 * time.Millisecond)
212→		}
213→		_ = s.SendKeys("Enter")
214→		time.Sleep(500 * time.Millisecond)
215→	}
216→	s.stableAtSend = ""
217→
218→	return s, nil
219→}
