 33→	if errors.Is(err, context.DeadlineExceeded) {
 34→		return true
 35→	}
 36→	transientPatterns := []string{
 37→		"INTERNAL",
 38→		"Incomplete JSON segment",
 39→		"429",
 40→		"TooManyRequests",
 41→		"RESOURCE_EXHAUSTED",
 42→		"UNAVAILABLE",
 43→		"DEADLINE_EXCEEDED",
 44→		"unexpected critical error",
 45→	}
 46→	for _, p := range transientPatterns {
 47→		if strings.Contains(out.Stderr, p) {
 48→			return true
 49→		}
 50→	}
 51→	return false
 52→}
