 54→func (g *Gemini) Bootstrap() error {
 55→	// Pre-configure auth so gemini doesn't show the onboarding dialog.
 56→	home, err := os.UserHomeDir()
 57→	if err != nil {
 58→		return fmt.Errorf("get home dir: %w", err)
 59→	}
 60→	dir := filepath.Join(home, ".gemini")
 61→	if err := os.MkdirAll(dir, 0o755); err != nil {
 62→		return fmt.Errorf("mkdir %s: %w", dir, err)
 63→	}
 64→	config := `{"security":{"auth":{"selectedType":"gemini-api-key"}}}`
 65→	return os.WriteFile(filepath.Join(dir, "settings.json"), []byte(config), 0o644)
 66→}
 67→
 68→func (g *Gemini) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 69→	cfg := &runConfig{Model: geminiDefaultModel}
 70→	for _, o := range opts {
 71→		o(cfg)
 72→	}
 73→
 74→	// Per-prompt timeout so a slow response gets killed early enough to
 75→	// retry within the test's overall budget.
 76→	timeout := 60 * time.Second
 77→	if cfg.PromptTimeout > 0 {
 78→		timeout = cfg.PromptTimeout
 79→	}
 80→	promptCtx, cancel := context.WithTimeout(ctx, timeout)
 81→	defer cancel()
 82→
 83→	args := []string{"-p", prompt, "--model", cfg.Model, "-y"}
 84→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "-y"}
 85→	cmd := exec.CommandContext(promptCtx, g.Binary(), args...)
 86→	cmd.Dir = dir
 87→	cmd.Stdin = nil
 88→	cmd.Env = append(filterEnv(os.Environ(), "ENTIRE_TEST_TTY"), "ACCESSIBLE=1")
 89→	setupProcessGroup(cmd)
 90→	cmd.WaitDelay = 5 * time.Second
 91→
 92→	var stdout, stderr strings.Builder
 93→	cmd.Stdout = &stdout
 94→	cmd.Stderr = &stderr
 95→
 96→	err := cmd.Run()
 97→	exitCode := 0
 98→	if err != nil {
 99→		exitErr := &exec.ExitError{}
100→		if errors.As(err, &exitErr) {
101→			exitCode = exitErr.ExitCode()
102→		} else {
103→			exitCode = -1
104→		}
105→		// Wrap the prompt-level deadline so IsTransientError can detect it.
106→		// cmd.Run() returns "signal: killed", not the context error.
107→		if promptCtx.Err() == context.DeadlineExceeded {
108→			err = fmt.Errorf("%w: %w", err, context.DeadlineExceeded)
109→		}
110→	}
111→
112→	return Output{
113→		Command:  g.Binary() + " " + strings.Join(displayArgs, " "),
114→		Stdout:   stdout.String(),
115→		Stderr:   stderr.String(),
116→		ExitCode: exitCode,
117→	}, err
118→}
119→
120→func (g *Gemini) StartSession(ctx context.Context, dir string) (Session, error) {
121→	name := fmt.Sprintf("gemini-test-%d", time.Now().UnixNano())
122→	// Unset CI and GITHUB_ACTIONS so gemini doesn't force headless mode —
123→	// it checks both in isHeadlessMode() and skips interactive TUI entirely.
124→	s, err := NewTmuxSession(name, dir, []string{"CI", "GITHUB_ACTIONS", "ENTIRE_TEST_TTY"}, "env", "ACCESSIBLE=1", g.Binary(), "--model", geminiDefaultModel, "-y")
125→	if err != nil {
126→		return nil, err
127→	}
128→
129→	// Dismiss startup dialogs (auth, workspace trust, etc.)
130→	for range 10 {
131→		content, err := s.WaitFor(`(Type your message|trust|Enter to select|Enter to confirm)`, 30*time.Second)
132→		if err != nil {
133→			_ = s.Close()
134→			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
135→		}
136→		if strings.Contains(content, "Type your message") {
137→			break
138→		}
139→		_ = s.SendKeys("Enter")
140→		time.Sleep(500 * time.Millisecond)
141→	}
142→	s.stableAtSend = ""
143→
144→	return s, nil
145→}
