 78→func (d *Droid) Bootstrap() error {
 79→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
 80→	if apiKey == "" {
 81→		return nil
 82→	}
 83→
 84→	home, err := os.UserHomeDir()
 85→	if err != nil {
 86→		return fmt.Errorf("get home dir: %w", err)
 87→	}
 88→	dir := filepath.Join(home, ".factory")
 89→	if err := os.MkdirAll(dir, 0o755); err != nil {
 90→		return fmt.Errorf("mkdir %s: %w", dir, err)
 91→	}
 92→
 93→	settingsPath := filepath.Join(dir, "settings.json")
 94→
 95→	// Read existing settings to merge (hooks may already be configured
 96→	// in the repo-local .factory/settings.json, but the global config
 97→	// at ~/.factory/settings.json might have other pre-existing entries).
 98→	var settings droidSettings
 99→	if data, readErr := os.ReadFile(settingsPath); readErr == nil {
100→		// Best-effort merge: ignore parse errors and start fresh
101→		_ = json.Unmarshal(data, &settings)
102→	}
103→
104→	// Replace or add the BYOK model entry.
105→	byokModel := droidCustomModel{
106→		DisplayName:    droidCustomModelDisplayName,
107→		Model:          droidCustomModelBaseID,
108→		BaseURL:        "https://api.anthropic.com",
109→		APIKey:         apiKey,
110→		Provider:       "anthropic",
111→		MaxOutputToken: 8192,
112→	}
113→
114→	found := false
115→	for i, m := range settings.CustomModels {
116→		if m.Model == byokModel.Model {
117→			settings.CustomModels[i] = byokModel
118→			found = true
119→			break
120→		}
121→	}
122→	if !found {
123→		settings.CustomModels = append(settings.CustomModels, byokModel)
124→	}
125→
126→	data, err := json.MarshalIndent(settings, "", "  ")
127→	if err != nil {
128→		return fmt.Errorf("marshal settings: %w", err)
129→	}
130→	return os.WriteFile(settingsPath, data, 0o644)
131→}
