582→// GetCheckpointTrailer extracts the Entire-Checkpoint trailer value from a
583→// code commit. Returns the trimmed trailer value, or an empty string if the
584→// trailer is not present.
585→func GetCheckpointTrailer(t *testing.T, dir string, ref string) string {
586→	t.Helper()
587→
588→	return GitOutput(t, dir, "log", "-1", "--format=%(trailers:key=Entire-Checkpoint,valueonly)", ref)
589→}
