			// Pattern lost — reset
			matchedAt = time.Time{}
			lastStable = ""
			time.Sleep(pollInterval)
			continue
		}

		// Detect content change since Send was called
		if !contentChanged && stable != s.stableAtSend {
			contentChanged = true
		}

		if stable != lastStable {
			// Pattern matches but content is still changing — reset settle timer
			matchedAt = time.Now()
